import {createSkillCore} from './skill-core.js';
export function createSkillsPipeline(parent){
const stages=[
 {name:'Understand the data',short:'Data',verb:'Find the question.',text:'Useful intelligence begins with understanding what the data can—and cannot—tell us.',tools:['Python','Pandas','Jupyter','Data analysis','Feature engineering'],repo:'EconML-Projects',project:'EconML',caption:'RAW OBSERVATIONS → STRUCTURED FEATURES'},
 {name:'Learn the patterns',short:'Learning',verb:'Turn patterns into possibilities.',text:'Build a baseline, test an idea, and learn from the result. Iterate with purpose.',tools:['scikit-learn','PyTorch','Machine learning','Deep learning','Google Colab'],repo:'NOAI-Preparation-Guide',project:'NOAI Preparation Guide',caption:'FEATURES → LEARNING → PREDICTION'},
 {name:'Interpret the world',short:'Perception',verb:'Give information context.',text:'Explore how visual features and spatial relationships help a machine make sense of its surroundings.',tools:['Computer vision','Image segmentation','Spatial perception','Robotics'],repo:'NATERIDA',project:'NATERIDA',caption:'PIXELS → FEATURES → SPATIAL UNDERSTANDING'},
 {name:'Make it useful',short:'Building',verb:'Put the idea in someone’s hands.',text:'Bring the work into an interface people can use—connecting the model, the service, and the experience.',tools:['React','Next.js','TypeScript','Python / Flask','Supabase','HTML','CSS','Responsive design'],repo:'Anvaya',project:'Anvaya',caption:'MODEL → SERVICE → INTERFACE'}
];
const el=document.createElement('section');el.className='skills-pipeline';el.setAttribute('aria-label','How I build: a journey through my skills');
el.innerHTML=`<div class="pipeline-haze"></div><div class="pipeline-opening"><p class="eyebrow">07 / FROM CURIOSITY TO CAPABILITY</p><h2>An idea is the beginning.<br><em>Here’s how I build it.</em></h2></div><div class="pipeline-main"><div class="pipeline-copy"><p class="eyebrow pipeline-count"></p><h2 class="pipeline-name"></h2><h3 class="pipeline-verb"></h3><p class="pipeline-description"></p><div class="pipeline-tools"></div><a class="pipeline-evidence" target="_blank" rel="noopener"></a></div><div class="pipeline-visual"><canvas aria-hidden="true"></canvas><p class="pipeline-caption"></p><small>CONCEPT ILLUSTRATION</small></div></div><div class="pipeline-summary"><p class="eyebrow">THE COMPLETE TOOLKIT</p><h2>Different skills.<br><em>One connected practice.</em></h2><div class="toolkit-grid">${stages.map((s,i)=>`<article><button data-jump="${i}"><span>0${i+1}</span>${s.name} ↗</button><p>${s.tools.join(' · ')}</p><a href="https://github.com/DeV-PrasiddhA/${s.repo}" target="_blank" rel="noopener">In practice: ${s.project} ↗</a></article>`).join('')}</div><p class="pipeline-coda">These are the tools. My experiences shape how I use them.</p></div><nav class="pipeline-nav" aria-label="Skills chapters">${stages.map((s,i)=>`<button data-jump="${i}"><span>0${i+1}</span>${s.short}</button>`).join('')}<button data-jump="4">All skills</button><i class="pipeline-nav-line"></i><b class="pipeline-nav-signal"></b></nav>`;
parent.insertBefore(el,parent.querySelector('.lp-controls'));
const q=s=>el.querySelector(s),clamp=x=>Math.max(0,Math.min(1,x)),ease=x=>{x=clamp(x);return x*x*(3-2*x)};
el.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{const p=document.querySelector('#projects'),start=p.offsetTop+(p.offsetHeight-innerHeight)*.9;const t=Number(b.dataset.jump)===4?18.9:9.65+Number(b.dataset.jump)*2.15+.5;scrollTo({top:start+(t-1.5)*innerHeight,behavior:document.querySelector('#motion').getAttribute('aria-pressed')==='true'?'instant':'smooth'});});
const core=createSkillCore(q('.pipeline-summary'),stages);
let current=-1,time=0,progress=0,stop=false,shown=false,last=0;
const canvas=q('canvas'),ctx=canvas.getContext('2d');
// A perspective field shared by all four chapters; scroll moves the camera.
const particles=Array.from({length:240},(_,i)=>({a:i*2.399963,r:2.2+(i%11)*.22,z:2+(i%40)*.42}));
let pointerX=0,pointerY=0,lookX=0,lookY=0,previousProgress=0,velocity=0;
el.addEventListener('pointermove',e=>{pointerX=(e.clientX/innerWidth-.5)*.18;pointerY=(e.clientY/innerHeight-.5)*.1});
el.addEventListener('pointerleave',()=>{pointerX=pointerY=0});
function shape(i,m){const p=particles[i],layer=i%6,row=Math.floor(i/6)%8,col=Math.floor(i/48);if(m===0)return [Math.cos(p.a)*p.r,Math.sin(p.a)*p.r,1.4+((p.z-Math.min(progress,1)*7)%16+16)%16];if(m===1)return [(row-3.5)*.68,(col-2)*.95,3+layer*2.15];if(m===2){const angle=i/240*Math.PI*2;return [Math.cos(angle)*(2.6+(i%4)*.15),Math.sin(angle)*(1.65+(i%3)*.16),3+(i%12)*.75];}return [(i%12-5.5)*.45,(Math.floor(i/12)%10-4.5)*.34,4+Math.floor(i/120)*3];}
function draw(ms){requestAnimationFrame(draw);const dt=Math.min((ms-last)/1000,.04);last=ms;if(!shown||!ctx||document.hidden)return;if(!stop)time+=dt;
const w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio,2);if(!w||!h)return;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);
lookX+=((stop?0:pointerX)-lookX)*.035;lookY+=((stop?0:pointerY)-lookY)*.035;velocity+=(Math.min(.7,Math.abs(progress-previousProgress)*35)-velocity)*.08;previousProgress=progress;
const m=Math.min(3,Math.floor(progress)),f=progress-m,blend=ease(f/.58),mobile=w<760,cx=w*.5,cy=h*(mobile?.34:.43),focal=Math.min(w,h)*(.82+Math.sin(progress*Math.PI/2)*.065);
const chapterFade=(m===0?1:ease(f/.22))*(m===3?1:1-ease((f-.83)/.17));
const project=(x,y,z)=>{const angle=stop?0:Math.sin(progress*1.1)*.09,yaw=stop?0:Math.sin(progress*1.4)*.12,dx=x*Math.cos(yaw)-z*Math.sin(yaw),dz=Math.max(.9,z*Math.cos(yaw)+x*Math.sin(yaw)-Math.sin(progress*.9)*.6),xx=dx*Math.cos(angle)-y*Math.sin(angle),yy=dx*Math.sin(angle)+y*Math.cos(angle);return {x:cx+(xx-lookX*dz)*focal/dz,y:cy+(yy-lookY*dz)*focal/dz,k:focal/dz,z:dz}};
const glow=ctx.createRadialGradient(cx,cy,0,cx,cy,w*.55);glow.addColorStop(0,'#123b4360');glow.addColorStop(.4,'#09212955');glow.addColorStop(1,'#020a1000');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);
const points=particles.map((p,i)=>{const a=shape(i,Math.max(0,m-1)),b=shape(i,m);let x=a[0]+(b[0]-a[0])*blend,y=a[1]+(b[1]-a[1])*blend,z=a[2]+(b[2]-a[2])*blend;return project(x,y,Math.max(1,z))});
// Perspective rails give the scene a floor and a continuous direction of travel.
ctx.lineWidth=1;for(let j=-7;j<=7;j++){const near=project(j*.8,2.8,1),far=project(j*.8,2.8,24);ctx.strokeStyle='#65b7bc20';ctx.beginPath();ctx.moveTo(near.x,near.y);ctx.lineTo(far.x,far.y);ctx.stroke()}for(let j=0;j<18;j++){const z=1+((j*1.3-progress*3)%23+23)%23,a=project(-8,2.8,z),b=project(8,2.8,z);ctx.strokeStyle='#65b7bc18';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}
ctx.globalAlpha=chapterFade;if(m===1||m===2){for(let i=0;i<points.length;i++){const a=points[i];for(const d of [6,48]){const b=points[i+d];if(!b)continue;const dist=Math.hypot(a.x-b.x,a.y-b.y);if(dist>w*.38)continue;ctx.strokeStyle=m===1?'#70c9cf25':'#77cdd019';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();if(i%9===0){const u=stop?.5:(time*.28+i*.13)%1;ctx.fillStyle='#ffe2a6';ctx.beginPath();ctx.arc(a.x+(b.x-a.x)*u,a.y+(b.y-a.y)*u,1.8,0,Math.PI*2);ctx.fill()}}}}
ctx.globalAlpha=1;points.forEach((p,i)=>{const alpha=Math.min(.9,1.9/p.z),r=Math.min(3.5,p.k*.018);ctx.globalAlpha=alpha;ctx.fillStyle=i%8===0?'#f4ce8c':'#96e4e5';if(i%8===0){ctx.shadowColor='#eac585';ctx.shadowBlur=12}ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;if(!stop&&velocity>.015){ctx.strokeStyle='#acd9db44';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+(p.x-cx)*velocity*.12,p.y+(p.y-cy)*velocity*.12);ctx.stroke()}if(m===0&&i%4===0){ctx.font=`${Math.max(8,Math.min(14,p.k*.12))}px monospace`;ctx.fillText((i*137%997).toString().padStart(3,'0'),p.x+5,p.y-4)}});ctx.globalAlpha=1;
ctx.globalAlpha=chapterFade;if(m===2){const scan=stop?.5:(time*.18)%1;for(let j=0;j<3;j++){const a=project(-2.5+j*.8,-1.6+j*.4,3+j*2),b=project(2.5-j*.3,1.6-j*.15,3+j*2);ctx.strokeStyle='#a0ded880';ctx.setLineDash([8,5]);ctx.strokeRect(a.x,a.y,b.x-a.x,b.y-a.y);ctx.setLineDash([]);ctx.fillStyle='#a5eee91c';ctx.fillRect(a.x,a.y+(b.y-a.y)*scan,b.x-a.x,3)}}
if(m===3){for(let j=2;j>=0;j--){const a=project(-2.5,-1.5,4+j*2),b=project(2.5,1.5,4+j*2);ctx.fillStyle='#07171ec9';ctx.fillRect(a.x,a.y,b.x-a.x,b.y-a.y);ctx.strokeStyle='#9cd3cf66';ctx.strokeRect(a.x,a.y,b.x-a.x,b.y-a.y);ctx.strokeStyle='#e5c48a';ctx.beginPath();for(let k=0;k<20;k++){const x=a.x+(b.x-a.x)*(.08+k*.044),y=a.y+(b.y-a.y)*(.7-k*.018+Math.sin(k*.9)*.05);k?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();ctx.fillStyle='#b6d1d0';ctx.font='10px monospace';ctx.fillText(['BUILD / DEPLOY','MODEL / SERVICE','DATA / INSIGHT'][j],a.x+12,a.y+20)}}
ctx.globalAlpha=1;
// Readable labels inhabit the field, clear of the chapter copy below.
ctx.globalAlpha=chapterFade;const labels=stages[m].tools.slice(0,4);labels.forEach((label,i)=>{const side=i%2?1:-1,row=Math.floor(i/2),x=cx+side*w*(mobile?.26:.29),y=h*(mobile?.18:.23)+row*h*.17;const source=project(side*2,row?1:-1,5);ctx.strokeStyle='#d9bf7d55';ctx.beginPath();ctx.moveTo(source.x,source.y);ctx.lineTo(x,y);ctx.stroke();ctx.font=`${mobile?10:13}px "DM Sans",sans-serif`;const tw=ctx.measureText(label).width;ctx.fillStyle='#06141de8';ctx.fillRect(x-tw/2-12,y-14,tw+24,28);ctx.strokeStyle='#afcfc740';ctx.strokeRect(x-tw/2-12,y-14,tw+24,28);ctx.fillStyle='#e4d3af';ctx.textAlign='center';ctx.fillText(label,x,y+4);ctx.textAlign='left'});ctx.globalAlpha=1;
// The same warm signal winds through every chapter, anchoring the continuous shot.
const signalPath=u=>project(Math.sin(u*5+progress*.7)*1.5,Math.cos(u*4+progress*.45)*.7,2+u*16);
ctx.save();ctx.globalCompositeOperation='screen';ctx.beginPath();for(let j=0;j<=70;j++){const p=signalPath(j/70);j?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)}ctx.strokeStyle='#e9be6b25';ctx.lineWidth=1.2;ctx.stroke();
for(let j=0;j<3;j++){const u=stop?.5:((time*.09+j/3)%1),p=signalPath(1-u),radius=12+p.k*.12,g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,radius);g.addColorStop(0,'#fff2ce');g.addColorStop(.07,'#ffe1a5cc');g.addColorStop(.25,'#efbe6d30');g.addColorStop(1,'#efbe6d00');ctx.fillStyle=g;ctx.fillRect(p.x-radius,p.y-radius,radius*2,radius*2)}ctx.restore();
// Close foreground motes soften the depth without obscuring the skill labels.
ctx.globalCompositeOperation='screen';for(let j=0;j<12;j++){const a=j*2.399+progress*.18+(stop?0:time*.012),radius=Math.min(w,h)*(.48+(j%3)*.13),x=cx+Math.cos(a)*radius,y=cy+Math.sin(a)*radius,r=6+j%4*3;const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,j%3?'#8bd3dc18':'#e8bc7925');g.addColorStop(1,'#6dc7d000');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}ctx.globalCompositeOperation='source-over';
}

requestAnimationFrame(draw);
return {update(t,paused){core.update(t,paused);stop=paused;const entrance=ease((t-7.8)/.9),intro=1-ease((t-9.1)/.6),overview=ease((t-18.35)/.7);shown=t>7.8&&overview<1;progress=clamp((t-9.65)/8.6)*4;el.style.opacity=entrance;el.style.visibility=t>7.8?'visible':'hidden';el.inert=t<7.8;
q('.pipeline-opening').style.opacity=intro;q('.pipeline-main').style.opacity=(1-intro)*(1-overview);q('.pipeline-main').inert=intro>.95||overview>.9;q('.pipeline-summary').style.opacity=overview;q('.pipeline-summary').inert=overview<.9;q('.pipeline-nav').style.opacity=ease((t-9)/.6);q('.pipeline-nav').inert=t<9;
const i=Math.min(3,Math.floor(progress)),phase=progress-i,copyFade=(i===0?1:ease(phase/.22))*(i===3?1:1-ease((phase-.83)/.17));q('.pipeline-copy').style.opacity=copyFade;q('.pipeline-copy').style.transform=paused?'none':`translateY(${(1-copyFade)*12}px)`;q('.pipeline-copy').inert=copyFade<.2;if(i!==current){current=i;const s=stages[i];q('.pipeline-count').textContent=`0${i+1} / THE PROCESS`;q('.pipeline-name').textContent=s.name;q('.pipeline-verb').textContent=s.verb;q('.pipeline-description').textContent=s.text;q('.pipeline-tools').innerHTML=s.tools.map(x=>`<span>${x}</span>`).join('');q('.pipeline-evidence').textContent=`Applied in ${s.project} ↗`;q('.pipeline-evidence').href='https://github.com/DeV-PrasiddhA/'+s.repo;q('.pipeline-caption').textContent=s.caption;}
el.querySelectorAll('.pipeline-nav button').forEach((b,j)=>b.setAttribute('aria-current',String(overview>.5?j===4:j===i)));q('.pipeline-nav-signal').style.left=(10+clamp(progress/4)*80)+'%';
}};
}
